import { useState, useMemo, useEffect } from 'react';
import {
  LayoutDashboard, Package, ShoppingCart, FileText, Truck, ArrowDownToLine, ArrowUpFromLine,
  Boxes, RotateCcw, ClipboardList, Bell, History, Search, Plus, X, CheckCircle2, AlertCircle,
  AlertTriangle, Clock, Info, Ban, ShieldAlert, TrendingDown, CalendarClock, Thermometer,
  Lock, Eye, Filter, Trash2, PackageCheck, ClipboardCheck, BarChart3,
} from 'lucide-react';
import type {
  StockItem, StockLot, StockMovement, NeedExpression, Quotation, Reception, StockAlert,
  NominalDispensing, ServiceDotation, ProductReturn, Inventory, Supplier,
  NeedExpressionStatus, QuotationStatus, ReceptionDecision, AlertLevel, AlertStatus,
  MovementType, ReturnDecision, DotationStatus, DispensingStatus,
} from '@/types';
import { Card, CardHeader, Badge, Button, Select, TextArea, EmptyState, SectionTitle } from '@/components/ui';
import {
  pharmacyItems as initialItems, pharmacyLots as initialLots, pharmacyMovements as initialMovements,
  pharmacyNeedExpressions as initialNeedExpressions, pharmacyQuotations as initialQuotations,
  pharmacyReceptions as initialReceptions, pharmacySuppliers as initialSuppliers,
  pharmacyAlerts as initialAlerts, pharmacyDispensing as initialDispensing,
  pharmacyDotations as initialDotations, pharmacyReturns as initialReturns,
  pharmacyInventories as initialInventories,
} from '@/data/pharmacyStock';
import { formatFCFA, formatDate, formatDateShort } from '@/utils/format';

type TabId = 'dashboard' | 'items' | 'needs' | 'quotations' | 'receptions' | 'entries' | 'dispensing' | 'dotations' | 'returns' | 'inventories' | 'alerts' | 'movements';
const TABS: { id: TabId; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'dashboard', label: 'Tableau de bord', icon: LayoutDashboard }, { id: 'items', label: 'Articles', icon: Package },
  { id: 'needs', label: 'Expressions de besoin', icon: ShoppingCart }, { id: 'quotations', label: 'Cotations', icon: FileText },
  { id: 'receptions', label: 'Réceptions', icon: Truck }, { id: 'entries', label: 'Entrées en stock', icon: ArrowDownToLine },
  { id: 'dispensing', label: 'Sorties nominatives', icon: ArrowUpFromLine }, { id: 'dotations', label: 'Dotations aux services', icon: Boxes },
  { id: 'returns', label: 'Retours', icon: RotateCcw }, { id: 'inventories', label: 'Inventaires', icon: ClipboardList },
  { id: 'alerts', label: 'Alertes', icon: Bell }, { id: 'movements', label: 'Historique des mouvements', icon: History },
];
const CAT: Record<string, string> = { medicaments: 'Médicaments', 'dispositifs-medicaux': 'Dispositifs médicaux', 'consommables-soins': 'Consommables de soins', 'produits-sensibles': 'Produits sensibles', 'produits-thermosensibles': 'Produits thermos-sensibles' };
const MV_LABEL: Record<MovementType, string> = { 'reception-conforme': 'Réception conforme', 'retour-service': 'Retour service', 'retour-patient': 'Retour patient', 'regularisation-positive': 'Régularisation +', 'transfert-entrant': 'Transfert entrant', 'reintegration-quarantaine': 'Réintégration quarantaine', 'sortie-nominative': 'Sortie nominative', 'dotation-service': 'Dotation service', 'sortie-diverse': 'Sortie diverse', 'consommation-automate': 'Consommation automate', 'consommation-manuelle': 'Consommation manuelle', 'regularisation-negative': 'Régularisation −', 'transfert-sortant': 'Transfert sortant', destruction: 'Destruction', 'retour-fournisseur': 'Retour fournisseur' };
const NEED_LABEL: Record<NeedExpressionStatus, string> = { brouillon: 'Brouillon', soumise: 'Soumise', 'en-validation': 'En validation', validee: 'Validée', 'validee-partiellement': 'Validée partiellement', rejetee: 'Rejetée', 'transformee-consultation': 'Transformée', cloturee: 'Clôturée' };
const QUOTE_LABEL: Record<QuotationStatus, string> = { recue: 'Reçue', 'en-comparaison': 'En comparaison', retenue: 'Retenue', 'en-validation': 'En validation', validee: 'Validée', rejetee: 'Rejetée', expiree: 'Expirée' };
const REC_LABEL: Record<ReceptionDecision, string> = { conforme: 'Conforme', 'partiellement-conforme': 'Partiellement conforme', 'non-conforme': 'Non conforme', quarantaine: 'Quarantaine', 'retourne-fournisseur': 'Retourné fournisseur' };
const ALERT_CFG: Record<AlertLevel, { label: string; icon: typeof Info; color: 'navy' | 'amber' | 'blue' | 'red'; bg: string; text: string }> = { info: { label: 'Information', icon: Info, color: 'navy', bg: 'bg-navy-100', text: 'text-navy-600' }, surveiller: { label: 'À surveiller', icon: Eye, color: 'blue', bg: 'bg-medical-100', text: 'text-medical-600' }, important: { label: 'Important', icon: AlertTriangle, color: 'amber', bg: 'bg-amber-100', text: 'text-amber-600' }, critique: { label: 'Critique', icon: ShieldAlert, color: 'red', bg: 'bg-red-100', text: 'text-red-600' } };
const ALERT_ST: Record<AlertStatus, string> = { nouvelle: 'Nouvelle', 'prise-en-charge': 'Prise en charge', 'en-cours': 'En cours', resolue: 'Résolue', justifiee: 'Justifiée', cloturee: 'Clôturée' };
const DISP_ST: Record<DispensingStatus, string> = { 'a-preparer': 'À préparer', preparee: 'Préparée', delivree: 'Délivrée', 'partiellement-delivree': 'Partiellement délivrée', 'non-delivree': 'Non délivrée', retournee: 'Retournée' };
const DOT_ST: Record<DotationStatus, string> = { demandee: 'Demandée', validee: 'Validée', preparee: 'Préparée', delivree: 'Délivrée', 'recue-service': 'Reçue service', 'partiellement-servie': 'Partiellement servie', rejetee: 'Rejetée' };
const RET_ST: Record<ReturnDecision, string> = { 'remis-stock': 'Remis en stock', quarantaine: 'Quarantaine', 'non-reutilisable': 'Non réutilisable', 'a-detruire': 'À détruire', 'retourne-fournisseur': 'Retourné fournisseur' };
const INV_TYPE: Record<string, string> = { complet: 'Complet', tournant: 'Tournant', 'cible-categorie': 'Ciblé catégorie', 'cible-emplacement': 'Ciblé emplacement', 'cible-article': 'Ciblé article', 'comptage-lot': 'Comptage lot' };
const INV_ST: Record<string, string> = { 'en-cours': 'En cours', valide: 'Validé', cloture: 'Clôturé' };
const SERVICES = ['Pharmacie', 'Soins infirmiers', 'Bloc opératoire', 'Réanimation', 'Hospitalisation', 'Urgences', 'Consultation externe', 'Cardiologie'];
const ENTRY_TYPES: { value: MovementType; label: string }[] = [{ value: 'reception-conforme', label: 'Réception conforme' }, { value: 'retour-service', label: 'Retour service' }, { value: 'retour-patient', label: 'Retour patient' }, { value: 'regularisation-positive', label: 'Régularisation +' }, { value: 'transfert-entrant', label: 'Transfert entrant' }, { value: 'reintegration-quarantaine', label: 'Réintégration quarantaine' }];
const ENTRY_MV = ['reception-conforme', 'retour-service', 'retour-patient', 'regularisation-positive', 'transfert-entrant', 'reintegration-quarantaine'];
const daysUntil = (s: string) => { const t = new Date(); t.setHours(0, 0, 0, 0); const d = new Date(s); d.setHours(0, 0, 0, 0); return Math.round((d.getTime() - t.getTime()) / 86400000); };
const isExpired = (s: string) => daysUntil(s) < 0;
const todayISO = () => new Date().toISOString().split('T')[0];
const nowTime = () => new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
const inp = 'w-full px-3 py-2 rounded-lg border border-navy-200 text-sm text-navy-900 focus:outline-none focus:ring-2 focus:ring-medical-400 focus:border-transparent';
const inpSm = 'w-full px-3 py-1.5 rounded-lg border border-navy-200 text-sm focus:outline-none focus:ring-2 focus:ring-medical-400';
type TT = 'success' | 'error' | 'warning' | 'info';
interface Toast { id: number; type: TT; message: string }
const needColor = (s: NeedExpressionStatus): 'green' | 'red' | 'amber' | 'navy' | 'blue' => s === 'validee' ? 'green' : s === 'rejetee' ? 'red' : s === 'validee-partiellement' ? 'amber' : s === 'transformee-consultation' || s === 'cloturee' ? 'navy' : 'blue';
const Th = ({ children }: { children: React.ReactNode }) => <th className="px-4 py-3 font-medium">{children}</th>;
const Td = ({ children, className = '' }: { children: React.ReactNode; className?: string }) => <td className={`px-4 py-3 ${className}`}>{children}</td>;
const ThR = ({ children }: { children: React.ReactNode }) => <th className="px-4 py-3 font-medium text-right">{children}</th>;
const TdR = ({ children, className = '' }: { children: React.ReactNode; className?: string }) => <td className={`px-4 py-3 text-right ${className}`}>{children}</td>;
const trCls = 'border-b border-navy-50 hover:bg-navy-50/50';
const thead = 'border-b border-navy-100 text-left text-navy-500';

export default function PharmacyStock() {
  const [tab, setTab] = useState<TabId>('dashboard');
  const [items, setItems] = useState<StockItem[]>(initialItems);
  const [lots, setLots] = useState<StockLot[]>(initialLots);
  const [movements, setMovements] = useState<StockMovement[]>(initialMovements);
  const [needExpressions, setNeedExpressions] = useState<NeedExpression[]>(initialNeedExpressions);
  const [quotations, setQuotations] = useState<Quotation[]>(initialQuotations);
  const [receptions, setReceptions] = useState<Reception[]>(initialReceptions);
  const [alerts, setAlerts] = useState<StockAlert[]>(initialAlerts);
  const [dispensing, setDispensing] = useState<NominalDispensing[]>(initialDispensing);
  const [dotations, setDotations] = useState<ServiceDotation[]>(initialDotations);
  const [returns, setReturns] = useState<ProductReturn[]>(initialReturns);
  const [inventories, setInventories] = useState<Inventory[]>(initialInventories);
  const [suppliers] = useState<Supplier[]>(initialSuppliers);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const tid = { current: 0 };
  const showToast = (t: TT, m: string) => { tid.current++; setToasts((p) => [...p, { id: tid.current, type: t, message: m }]); };
  useEffect(() => { if (!toasts.length) return; const t = setTimeout(() => setToasts((p) => p.slice(1)), 4000); return () => clearTimeout(t); }, [toasts]);
  const supName = (id: string) => suppliers.find((s) => s.id === id)?.name ?? '—';
  const getItem = (id: string) => items.find((i) => i.id === id);
  const fefo = (id: string) => lots.filter((l) => l.itemId === id && l.availableQty > 0 && !l.blocked).sort((a, b) => new Date(a.expiryDate).getTime() - new Date(b.expiryDate).getTime());

  function recMv(type: MovementType, itemId: string, lotId: string | undefined, qty: number, origin: string, dest: string, author: string, ref: string, reason: string, before: number, after: number) {
    const it = getItem(itemId); if (!it) return;
    const lot = lotId ? lots.find((l) => l.id === lotId) : undefined;
    setMovements((p) => [{ id: `mv-${Date.now()}`, domain: 'pharmacy', date: todayISO(), time: nowTime(), type, itemId, itemName: it.name, lotId, lotNumber: lot?.lotNumber, quantity: qty, unit: it.unitDispensing, origin, destination: dest, author, reference: ref, stockBefore: before, stockAfter: after, reason }, ...p]);
  }
  function resetDemo() { setItems(initialItems); setLots(initialLots); setMovements(initialMovements); setNeedExpressions(initialNeedExpressions); setQuotations(initialQuotations); setReceptions(initialReceptions); setAlerts(initialAlerts); setDispensing(initialDispensing); setDotations(initialDotations); setReturns(initialReturns); setInventories(initialInventories); showToast('info', 'Démonstration réinitialisée — toutes les données sont restaurées à leur état initial.'); }

  // Dashboard
  const dash = useMemo(() => {
    const stockValue = items.reduce((s, i) => s + i.availableStock * i.lastPrice, 0);
    const avail = items.filter((i) => i.availableStock > i.minStock).length;
    const under = items.filter((i) => i.availableStock > 0 && i.availableStock <= i.minStock).length;
    const rupture = items.filter((i) => i.availableStock === 0).length;
    const exp = (n: number) => lots.filter((l) => { const d = daysUntil(l.expiryDate); return d >= 0 && d <= n && l.availableQty > 0; }).length;
    const expired = lots.filter((l) => isExpired(l.expiryDate) && l.availableQty > 0).length;
    const quar = items.filter((i) => i.quarantineStock > 0).length;
    const needsP = needExpressions.filter((n) => n.status === 'soumise' || n.status === 'en-validation').length;
    const quoteP = quotations.filter((q) => q.status === 'en-comparaison' || q.status === 'en-validation').length;
    const recP = receptions.filter((r) => r.decision === 'quarantaine').length;
    const dispToday = dispensing.filter((d) => d.date === todayISO()).length;
    const dotP = dotations.filter((d) => d.status === 'demandee' || d.status === 'validee').length;
    const invGaps = inventories.reduce((s, inv) => s + inv.entries.filter((e) => e.gap !== 0).length, 0);
    const activeAlerts = alerts.filter((a) => a.status !== 'resolue' && a.status !== 'cloturee').length;
    const cons: Record<string, { name: string; qty: number }> = {};
    for (const m of movements) if (['sortie-nominative', 'dotation-service', 'sortie-diverse', 'consommation-manuelle'].includes(m.type)) (cons[m.itemId] ??= { name: m.itemName, qty: 0 }).qty += m.quantity;
    const top5 = Object.values(cons).sort((a, b) => b.qty - a.qty).slice(0, 5);
    return { stockValue, avail, under, rupture, e30: exp(30), e60: exp(60), e90: exp(90), expired, quar, needsP, quoteP, recP, dispToday, dotP, invGaps, activeAlerts, top5 };
  }, [items, lots, movements, needExpressions, quotations, receptions, dispensing, dotations, inventories, alerts]);

  // Items
  const [itemSearch, setItemSearch] = useState(''); const [itemCat, setItemCat] = useState('all'); const [selItemId, setSelItemId] = useState<string | null>(null);
  const filteredItems = useMemo(() => { let r = items; if (itemCat !== 'all') r = r.filter((i) => i.category === itemCat); if (itemSearch.trim()) { const q = itemSearch.toLowerCase(); r = r.filter((i) => i.name.toLowerCase().includes(q) || i.code.toLowerCase().includes(q) || i.location.toLowerCase().includes(q)); } return r; }, [items, itemSearch, itemCat]);
  const selItem = selItemId ? items.find((i) => i.id === selItemId) : null;
  const selItemLots = selItem ? lots.filter((l) => l.itemId === selItem.id) : [];

  // Needs
  const [showNeedModal, setShowNeedModal] = useState(false); const [selNeedId, setSelNeedId] = useState<string | null>(null);
  const [needForm, setNeedForm] = useState({ service: 'Pharmacie', period: '', justification: '', urgency: 'normal' as 'normal' | 'urgent' | 'critique' });
  const [needFormItems, setNeedFormItems] = useState<{ itemId: string; requestedQty: number; comment: string }[]>([]);
  const [needValReason, setNeedValReason] = useState(''); const [needRejReason, setNeedRejReason] = useState('');
  const selNeed = selNeedId ? needExpressions.find((n) => n.id === selNeedId) : null;
  const submitNeed = () => {
    if (!needForm.period || !needForm.justification || !needFormItems.length) return showToast('error', 'Veuillez remplir tous les champs obligatoires.');
    const valid = needFormItems.filter((ni) => ni.itemId && ni.requestedQty > 0);
    if (!valid.length) return showToast('error', 'Veuillez ajouter au moins un article avec une quantité valide.');
    const id = `ne-${Date.now()}`, num = `EB-PHARM-${new Date().getFullYear()}-${String(needExpressions.length + 1).padStart(3, '0')}`;
    setNeedExpressions((p) => [{ id, domain: 'pharmacy', number: num, date: todayISO(), service: needForm.service, period: needForm.period, justification: needForm.justification, urgency: needForm.urgency, requester: 'Adjoua Mariam', status: 'soumise', items: valid.map((ni) => { const it = getItem(ni.itemId)!; return { itemId: ni.itemId, itemName: it.name, availableQty: it.availableStock, minStock: it.minStock, avgConsumption: it.avgConsumption, orderedQty: it.orderedQty, requestedQty: ni.requestedQty, unit: it.unitDispensing, supplierId: it.supplierId, proposedQty: Math.max(it.minStock * 2 - it.availableStock, ni.requestedQty), comment: ni.comment }; }), history: [{ timestamp: new Date().toISOString(), action: 'Création', detail: 'Créée par Adjoua Mariam' }, { timestamp: new Date().toISOString(), action: 'Soumission', detail: 'Soumise pour validation' }] }, ...p]);
    setShowNeedModal(false); setNeedForm({ service: 'Pharmacie', period: '', justification: '', urgency: 'normal' }); setNeedFormItems([]); showToast('success', `Expression de besoin ${num} créée et soumise.`);
  };
  const validateNeed = (id: string, partial: boolean) => { setNeedExpressions((p) => p.map((n) => n.id === id ? { ...n, status: partial ? 'validee-partiellement' : 'validee', validator: 'Dr. Yao N\'Guessan', items: n.items.map((it) => ({ ...it, validatedQty: partial ? Math.round(it.requestedQty * 0.7) : it.requestedQty })), history: [...n.history, { timestamp: new Date().toISOString(), action: 'Validation', detail: partial ? `Validation partielle — ${needValReason || 'Quantités ajustées'}` : 'Validation complète' }] } : n)); setSelNeedId(null); setNeedValReason(''); showToast('success', partial ? 'Expression validée partiellement.' : 'Expression validée.'); };
  const rejectNeed = (id: string) => { if (!needRejReason.trim()) return showToast('error', 'Veuillez indiquer le motif du rejet.'); setNeedExpressions((p) => p.map((n) => n.id === id ? { ...n, status: 'rejetee', validator: 'Dr. Yao N\'Guessan', rejectionReason: needRejReason, history: [...n.history, { timestamp: new Date().toISOString(), action: 'Rejet', detail: `Rejetée — ${needRejReason}` }] } : n)); setSelNeedId(null); setNeedRejReason(''); showToast('warning', 'Expression de besoin rejetée.'); };

  // Quotations
  const [selQuoteId, setSelQuoteId] = useState<string | null>(null); const [selReason, setSelReason] = useState('');
  const quotesByNeed = useMemo(() => { const g: Record<string, Quotation[]> = {}; for (const q of quotations) (g[q.needExpressionId] ??= []).push(q); return g; }, [quotations]);
  const selQuote = selQuoteId ? quotations.find((q) => q.id === selQuoteId) : null;
  const validateQuote = (id: string) => { const q = quotations.find((qq) => qq.id === id); if (!q) return; if (isExpired(q.expiryDate)) return showToast('error', `Impossible de valider : devis expiré le ${formatDateShort(q.expiryDate)}.`); if (!selReason.trim()) return showToast('error', 'Veuillez indiquer le motif de la sélection.'); setQuotations((p) => p.map((qq) => qq.id === id ? { ...qq, status: 'validee', selectionReason: selReason, validator: 'Dr. Yao N\'Guessan', history: [...qq.history, { timestamp: new Date().toISOString(), action: 'Validation', detail: `Validé — ${selReason}` }] } : qq)); setSelQuoteId(null); setSelReason(''); showToast('success', `Devis ${q.number} validé et retenu.`); };

  // Receptions
  const [selRecId, setSelRecId] = useState<string | null>(null); const [recChecks, setRecChecks] = useState<Record<string, boolean>>({});
  const selRec = selRecId ? receptions.find((r) => r.id === selRecId) : null;
  const applyDecision = (recId: string, decision: ReceptionDecision) => {
    const rec = receptions.find((r) => r.id === recId); if (!rec) return;
    setReceptions((p) => p.map((r) => r.id === recId ? { ...r, decision, history: [...r.history, { timestamp: new Date().toISOString(), action: 'Décision', detail: REC_LABEL[decision] }] } : r));
    if (decision === 'conforme' || decision === 'partiellement-conforme') {
      for (const ri of rec.items) { const acc = decision === 'conforme' ? ri.receivedQty : ri.acceptedQty; if (acc > 0) { const it = getItem(ri.itemId); if (!it) continue; const b = it.availableStock; setItems((p) => p.map((x) => x.id === ri.itemId ? { ...x, availableStock: x.availableStock + acc } : x)); recMv('reception-conforme', ri.itemId, undefined, acc, rec.supplierName, 'Pharmacie centrale', rec.receiver, rec.deliveryNoteNumber, `Réception ${REC_LABEL[decision]} — ${ri.itemName}`, b, b + acc); } }
      showToast('success', `Réception ${REC_LABEL[decision]} — stock mis à jour et mouvement enregistré.`);
    } else showToast('warning', `Réception marquée: ${REC_LABEL[decision]} — le stock n'est pas mis à jour.`);
    setSelRecId(null); setRecChecks({});
  };

  // Entries
  const [entryForm, setEntryForm] = useState({ type: 'reception-conforme' as MovementType, itemId: '', lotId: '', quantity: 0, origin: '' });
  const submitEntry = () => { if (!entryForm.itemId || entryForm.quantity <= 0) return showToast('error', 'Veuillez sélectionner un article et saisir une quantité valide.'); const it = getItem(entryForm.itemId); if (!it) return; const b = it.availableStock, a = b + entryForm.quantity; setItems((p) => p.map((x) => x.id === entryForm.itemId ? { ...x, availableStock: a } : x)); if (entryForm.lotId) setLots((p) => p.map((l) => l.id === entryForm.lotId ? { ...l, availableQty: l.availableQty + entryForm.quantity } : l)); recMv(entryForm.type, entryForm.itemId, entryForm.lotId || undefined, entryForm.quantity, entryForm.origin || '—', 'Pharmacie centrale', 'Kouadio Justin', `ENT-${Date.now()}`, `Entrée — ${MV_LABEL[entryForm.type]}`, b, a); showToast('success', `Entrée enregistrée : ${entryForm.quantity} ${it.unitDispensing} pour ${it.name}.`); setEntryForm({ type: 'reception-conforme', itemId: '', lotId: '', quantity: 0, origin: '' }); };

  // Dispensing
  const [showDispForm, setShowDispForm] = useState(false);
  const [dispForm, setDispForm] = useState({ patientName: '', prescriptionId: '', service: 'Consultation externe', prescriber: '', itemId: '', lotId: '', prescribedQty: 0, deliveredQty: 0 });
  const dispLots = useMemo(() => dispForm.itemId ? fefo(dispForm.itemId) : [], [dispForm.itemId, lots]);
  const dispBlocked = useMemo(() => { if (!dispForm.lotId) return null; const l = lots.find((x) => x.id === dispForm.lotId); if (!l) return null; if (l.blocked) return { r: 'Lot bloqué', d: l.blockedReason ?? 'Bloqué' }; if (isExpired(l.expiryDate)) return { r: 'Lot expiré', d: `Expiré le ${formatDateShort(l.expiryDate)}` }; if (l.quarantineQty > 0 && l.availableQty === 0) return { r: 'Quarantaine', d: 'Lot en quarantaine' }; return null; }, [dispForm.lotId, lots]);
  const submitDisp = () => { if (!dispForm.patientName || !dispForm.itemId || !dispForm.lotId || dispForm.deliveredQty <= 0) return showToast('error', 'Veuillez remplir tous les champs obligatoires.'); if (dispBlocked) return showToast('error', `Dispensation impossible : ${dispBlocked.r} — ${dispBlocked.d}`); const l = lots.find((x) => x.id === dispForm.lotId); if (!l || l.availableQty < dispForm.deliveredQty) return showToast('error', 'Quantité insuffisante dans ce lot.'); const it = getItem(dispForm.itemId)!; const b = it.availableStock, a = b - dispForm.deliveredQty; setItems((p) => p.map((x) => x.id === dispForm.itemId ? { ...x, availableStock: a } : x)); setLots((p) => p.map((x) => x.id === dispForm.lotId ? { ...x, availableQty: x.availableQty - dispForm.deliveredQty } : x)); const id = `nd-${Date.now()}`; setDispensing((p) => [{ id, patientId: `p-${Date.now()}`, patientName: dispForm.patientName, encounterId: `enc-${Date.now()}`, prescriptionId: dispForm.prescriptionId || `rx-${Date.now()}`, service: dispForm.service, prescriber: dispForm.prescriber || '—', itemId: dispForm.itemId, itemName: it.name, lotId: dispForm.lotId, lotNumber: l.lotNumber, prescribedQty: dispForm.prescribedQty || dispForm.deliveredQty, deliveredQty: dispForm.deliveredQty, date: todayISO(), pharmacist: 'Adjoua Mariam', status: 'delivree' }, ...p]); recMv('sortie-nominative', dispForm.itemId, dispForm.lotId, dispForm.deliveredQty, 'Pharmacie centrale', `Patient ${dispForm.patientName}`, 'Adjoua Mariam', dispForm.prescriptionId || `rx-${Date.now()}`, 'Dispensation nominative', b, a); showToast('success', `Dispensation enregistrée pour ${dispForm.patientName} — ${dispForm.deliveredQty} ${it.unitDispensing}.`); setShowDispForm(false); setDispForm({ patientName: '', prescriptionId: '', service: 'Consultation externe', prescriber: '', itemId: '', lotId: '', prescribedQty: 0, deliveredQty: 0 }); };

  // Dotations
  const [showDotForm, setShowDotForm] = useState(false);
  const [dotForm, setDotForm] = useState({ service: '', requester: '', itemId: '', lotId: '', requestedQty: 0, responsible: 'Adjoua Mariam' });
  const dotLots = useMemo(() => dotForm.itemId ? fefo(dotForm.itemId) : [], [dotForm.itemId, lots]);
  const submitDot = () => { if (!dotForm.service || !dotForm.itemId || !dotForm.lotId || dotForm.requestedQty <= 0) return showToast('error', 'Veuillez remplir tous les champs obligatoires.'); const l = lots.find((x) => x.id === dotForm.lotId); if (!l || l.availableQty < dotForm.requestedQty) return showToast('error', 'Quantité insuffisante.'); const it = getItem(dotForm.itemId)!; const b = it.availableStock, a = b - dotForm.requestedQty; setItems((p) => p.map((x) => x.id === dotForm.itemId ? { ...x, availableStock: a } : x)); setLots((p) => p.map((x) => x.id === dotForm.lotId ? { ...x, availableQty: x.availableQty - dotForm.requestedQty } : x)); const id = `dot-${Date.now()}`; setDotations((p) => [{ id, service: dotForm.service, requester: dotForm.requester || '—', itemId: dotForm.itemId, itemName: it.name, lotId: dotForm.lotId, lotNumber: l.lotNumber, requestedQty: dotForm.requestedQty, validatedQty: dotForm.requestedQty, deliveredQty: dotForm.requestedQty, date: todayISO(), responsible: dotForm.responsible, status: 'delivree', receiptAcknowledged: false }, ...p]); recMv('dotation-service', dotForm.itemId, dotForm.lotId, dotForm.requestedQty, 'Pharmacie centrale', dotForm.service, dotForm.responsible, id, `Dotation ${dotForm.service}`, b, a); showToast('success', `Dotation livrée à ${dotForm.service} — ${dotForm.requestedQty} ${it.unitDispensing}.`); setShowDotForm(false); setDotForm({ service: '', requester: '', itemId: '', lotId: '', requestedQty: 0, responsible: 'Adjoua Mariam' }); };

  // Returns
  const [showRetForm, setShowRetForm] = useState(false);
  const [retForm, setRetForm] = useState({ origin: '', itemId: '', lotId: '', quantity: 0, reason: '', packagingIntact: true, storageRespected: true, decision: 'remis-stock' as ReturnDecision });
  const retLots = useMemo(() => retForm.itemId ? lots.filter((l) => l.itemId === retForm.itemId && l.availableQty > 0) : [], [retForm.itemId, lots]);
  const submitRet = () => { if (!retForm.origin || !retForm.itemId || !retForm.lotId || retForm.quantity <= 0 || !retForm.reason) return showToast('error', 'Veuillez remplir tous les champs obligatoires.'); const l = lots.find((x) => x.id === retForm.lotId); if (!l) return; const it = getItem(retForm.itemId)!; const id = `ret-${Date.now()}`; setReturns((p) => [{ id, origin: retForm.origin, itemId: retForm.itemId, itemName: it.name, lotId: retForm.lotId, lotNumber: l.lotNumber, quantity: retForm.quantity, reason: retForm.reason, packagingIntact: retForm.packagingIntact, storageRespected: retForm.storageRespected, expiryDate: l.expiryDate, controlledBy: 'Kouadio Justin', decision: retForm.decision, date: todayISO() }, ...p]); if (retForm.decision === 'remis-stock') { const b = it.availableStock; setItems((p) => p.map((x) => x.id === retForm.itemId ? { ...x, availableStock: x.availableStock + retForm.quantity } : x)); setLots((p) => p.map((x) => x.id === retForm.lotId ? { ...x, availableQty: x.availableQty + retForm.quantity } : x)); recMv('retour-service', retForm.itemId, retForm.lotId, retForm.quantity, retForm.origin, 'Pharmacie centrale', 'Kouadio Justin', id, `Retour — ${retForm.reason}`, b, b + retForm.quantity); showToast('success', `Retour enregistré — remis en stock (${retForm.quantity} ${it.unitDispensing}).`); } else if (retForm.decision === 'quarantaine') { setLots((p) => p.map((x) => x.id === retForm.lotId ? { ...x, quarantineQty: x.quarantineQty + retForm.quantity, blocked: true, blockedReason: `Quarantaine — ${retForm.reason}` } : x)); showToast('warning', `Retour enregistré — mis en quarantaine (${retForm.quantity} ${it.unitDispensing}).`); } else showToast('warning', `Retour enregistré — ${RET_ST[retForm.decision]}.`); setShowRetForm(false); setRetForm({ origin: '', itemId: '', lotId: '', quantity: 0, reason: '', packagingIntact: true, storageRespected: true, decision: 'remis-stock' }); };

  // Inventories
  const [showInvForm, setShowInvForm] = useState(false);
  const [invForm, setInvForm] = useState({ type: 'tournant' as Inventory['type'], entries: [] as { itemId: string; countedQty: number; reason: string }[] });
  const submitInv = () => { const valid = invForm.entries.filter((e) => e.itemId && e.countedQty >= 0); if (!valid.length) return showToast('error', 'Veuillez ajouter au moins une ligne de comptage valide.'); const id = `inv-${Date.now()}`, num = `INV-PHARM-${new Date().getFullYear()}-${String(inventories.length + 1).padStart(3, '0')}`; const entries = valid.map((e) => { const it = getItem(e.itemId)!; const gap = e.countedQty - it.availableStock; return { id: `${id}-e${Math.random().toString(36).slice(2, 6)}`, itemId: e.itemId, itemName: it.name, theoreticalStock: it.availableStock, countedQty: e.countedQty, gap, gapValue: gap * it.lastPrice, reason: e.reason || (gap === 0 ? 'Conforme' : `Écart de ${gap}`), stockBefore: it.availableStock, stockAfter: e.countedQty }; }); setInventories((p) => [{ id, domain: 'pharmacy', number: num, type: invForm.type, date: todayISO(), entries, validator: 'Dr. Yao N\'Guessan', status: 'valide' }, ...p]); for (const e of valid) { const it = getItem(e.itemId)!; if (e.countedQty !== it.availableStock) { const b = it.availableStock; setItems((p) => p.map((x) => x.id === e.itemId ? { ...x, availableStock: e.countedQty } : x)); recMv(e.countedQty > b ? 'regularisation-positive' : 'regularisation-negative', e.itemId, undefined, Math.abs(e.countedQty - b), 'Pharmacie centrale', 'Pharmacie centrale', 'Adjoua Mariam', id, `Régularisation ${num}`, b, e.countedQty); } } showToast('success', `Inventaire ${num} validé — ${entries.filter((e) => e.gap !== 0).length} écart(s).`); setShowInvForm(false); setInvForm({ type: 'tournant', entries: [] }); };

  // Alerts
  const [alertLevel, setAlertLevel] = useState('all'); const [alertStatus, setAlertStatus] = useState('all');
  const filteredAlerts = useMemo(() => { let r = alerts; if (alertLevel !== 'all') r = r.filter((a) => a.level === alertLevel); if (alertStatus !== 'all') r = r.filter((a) => a.status === alertStatus); return r; }, [alerts, alertLevel, alertStatus]);
  const updateAlert = (id: string, st: AlertStatus, act: string) => { setAlerts((p) => p.map((a) => a.id === id ? { ...a, status: st, history: [...a.history, { timestamp: new Date().toISOString(), action: act, detail: `Statut: ${ALERT_ST[st]}` }] } : a)); showToast('success', `Alerte mise à jour: ${ALERT_ST[st]}.`); };

  // Movements
  const [mvF, setMvF] = useState({ type: 'all', itemId: 'all', category: 'all', status: 'all' });
  const filteredMv = useMemo(() => { let r = movements; if (mvF.type !== 'all') r = r.filter((m) => m.type === mvF.type); if (mvF.itemId !== 'all') r = r.filter((m) => m.itemId === mvF.itemId); if (mvF.category !== 'all') { const ids = items.filter((i) => i.category === mvF.category).map((i) => i.id); r = r.filter((m) => ids.includes(m.itemId)); } if (mvF.status === 'entree') r = r.filter((m) => ENTRY_MV.includes(m.type)); else if (mvF.status === 'sortie') r = r.filter((m) => !ENTRY_MV.includes(m.type)); return r; }, [movements, mvF, items]);

  // Shared UI
  const tIcons = { success: CheckCircle2, error: X, warning: AlertTriangle, info: Info };
  const tColors = { success: 'bg-green-50 border-green-200 text-green-800', error: 'bg-red-50 border-red-200 text-red-800', warning: 'bg-amber-50 border-amber-200 text-amber-800', info: 'bg-medical-50 border-medical-200 text-medical-800' };
  const tIconColors = { success: 'text-green-600', error: 'text-red-600', warning: 'text-amber-600', info: 'text-medical-600' };
  const Modal = ({ title, onClose, children, wide }: { title: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) => (
    <div className="fixed inset-0 bg-navy-900/40 flex items-center justify-center z-40 p-4" onClick={onClose}>
      <div className={`bg-white rounded-xl shadow-xl ${wide ? 'max-w-2xl' : 'max-w-lg'} w-full max-h-[90vh] overflow-y-auto`} onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between px-5 py-4 border-b border-navy-100 sticky top-0 bg-white z-10"><h3 className="font-semibold text-navy-900">{title}</h3><button onClick={onClose} className="text-navy-400 hover:text-navy-600 focus:outline-none focus-visible:ring-2 focus-visible:ring-medical-400 rounded"><X className="w-5 h-5" /></button></div>
        {children}
      </div>
    </div>
  );
  const ModalFooter = ({ onCancel, onSubmit, submitLabel }: { onCancel: () => void; onSubmit: () => void; submitLabel: string }) => (
    <div className="flex justify-end gap-2 px-5 py-4 border-t border-navy-100 sticky bottom-0 bg-white"><Button variant="secondary" size="sm" onClick={onCancel}>Annuler</Button><Button variant="primary" size="sm" onClick={onSubmit}><CheckCircle2 className="w-4 h-4 mr-1" />{submitLabel}</Button></div>
  );

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between flex-wrap gap-4">
        <div><h2 className="text-xl font-bold text-navy-900">Gestion du stock pharmacie</h2><p className="text-sm text-navy-500 mt-0.5">Suivi des articles, lots, mouvements, expressions de besoin, cotations et réceptions</p></div>
        <span title="Réinitialiser toutes les données de la démonstration"><Button variant="ghost" size="sm" onClick={resetDemo}><RotateCcw className="w-4 h-4 mr-1.5" />Réinitialiser la démonstration</Button></span>
      </div>

      {toasts.length > 0 && <div className="fixed top-4 right-4 z-50 space-y-2 max-w-md">{toasts.map((t) => { const Icon = tIcons[t.type]; return <div key={t.id} className={`flex items-start gap-3 px-4 py-3 rounded-lg border text-sm animate-fade-in ${tColors[t.type]}`}><Icon className={`w-4 h-4 mt-0.5 flex-shrink-0 ${tIconColors[t.type]}`} /><span className="flex-1">{t.message}</span><button onClick={() => setToasts((p) => p.filter((x) => x.id !== t.id))} className="flex-shrink-0 opacity-60 hover:opacity-100 focus:outline-none focus-visible:ring-2 focus-visible:ring-medical-400 rounded"><X className="w-3.5 h-3.5" /></button></div>; })}</div>}

      <div className="overflow-x-auto -mx-1 px-1 pb-1"><div className="flex gap-1 border-b border-navy-100 min-w-max">{TABS.map((t) => { const Icon = t.icon; return <button key={t.id} onClick={() => setTab(t.id)} className={`flex items-center gap-2 px-4 py-2.5 text-sm font-medium border-b-2 transition-colors whitespace-nowrap focus:outline-none focus-visible:ring-2 focus-visible:ring-medical-400 ${tab === t.id ? 'border-medical-600 text-medical-700' : 'border-transparent text-navy-500 hover:text-navy-700'}`}><Icon className="w-4 h-4" />{t.label}</button>; })}</div></div>

      {/* DASHBOARD */}
      {tab === 'dashboard' && <div className="space-y-6">
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
          {[
            { l: 'Valeur du stock', v: formatFCFA(dash.stockValue), i: Package, c: 'text-medical-600' },
            { l: 'Articles disponibles', v: dash.avail, i: CheckCircle2, c: 'text-green-600' },
            { l: 'Sous le minimum', v: dash.under, i: TrendingDown, c: 'text-amber-600' },
            { l: 'En rupture', v: dash.rupture, i: AlertCircle, c: 'text-red-600' },
            { l: 'Lots expirant ≤ 30j', v: dash.e30, i: CalendarClock, c: 'text-amber-600' },
            { l: 'Lots expirant ≤ 60j', v: dash.e60, i: CalendarClock, c: 'text-navy-500' },
            { l: 'Lots expirant ≤ 90j', v: dash.e90, i: CalendarClock, c: 'text-medical-600' },
            { l: 'Produits périmés', v: dash.expired, i: Ban, c: 'text-red-600' },
            { l: 'En quarantaine', v: dash.quar, i: Lock, c: 'text-amber-600' },
            { l: 'Expressions en attente', v: dash.needsP, i: ShoppingCart, c: 'text-medical-600' },
            { l: 'Cotations à valider', v: dash.quoteP, i: FileText, c: 'text-turquoise-600' },
            { l: 'Réceptions en attente', v: dash.recP, i: Truck, c: 'text-amber-600' },
            { l: 'Délivrances du jour', v: dash.dispToday, i: ArrowUpFromLine, c: 'text-green-600' },
            { l: 'Dotations en attente', v: dash.dotP, i: Boxes, c: 'text-medical-600' },
            { l: 'Écarts d\'inventaire', v: dash.invGaps, i: ClipboardCheck, c: 'text-amber-600' },
            { l: 'Alertes actives', v: dash.activeAlerts, i: Bell, c: 'text-red-600' },
          ].map((c) => { const Icon = c.i; return <Card key={c.l} className="p-4"><div className="flex items-center gap-2 mb-1"><Icon className={`w-4 h-4 ${c.c}`} /><span className="text-xs text-navy-500 font-medium">{c.l}</span></div><p className="text-xl font-bold text-navy-900">{c.v}</p></Card>; })}
        </div>
        <Card><CardHeader title="Top 5 articles les plus consommés" subtitle="Basé sur l'historique des mouvements de sortie" /><div className="p-5">{dash.top5.length === 0 ? <EmptyState icon={BarChart3} title="Aucune consommation enregistrée" /> : <div className="space-y-3">{dash.top5.map((item, idx) => { const max = Math.max(...dash.top5.map((t) => t.qty)); const pct = max > 0 ? (item.qty / max) * 100 : 0; return <div key={idx} className="flex items-center gap-3"><div className="w-48 flex-shrink-0"><p className="text-sm font-medium text-navy-800 truncate">{item.name}</p></div><div className="flex-1 h-7 bg-navy-50 rounded-lg overflow-hidden"><div className="h-full bg-gradient-to-r from-medical-500 to-turquoise-500 rounded-lg flex items-center justify-end pr-2 transition-all" style={{ width: `${pct}%` }}><span className="text-xs font-bold text-white">{item.qty}</span></div></div></div>; })}</div>}</div></Card>
      </div>}

      {/* ITEMS */}
      {tab === 'items' && <div className="space-y-4">
        <Card className="p-4"><div className="flex flex-wrap gap-3 items-end">
          <div className="flex-1 min-w-[200px]"><label className="block text-sm font-medium text-navy-700 mb-1">Recherche</label><div className="relative"><Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-navy-400" /><input type="text" value={itemSearch} onChange={(e) => setItemSearch(e.target.value)} placeholder="Nom, code ou emplacement..." className={inp + ' pl-9'} /></div></div>
          <div className="w-56"><Select label="Catégorie" value={itemCat} onChange={setItemCat} options={[{ value: 'all', label: 'Toutes les catégories' }, ...Object.entries(CAT).map(([value, label]) => ({ value, label }))]} /></div>
        </div></Card>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          <div className="lg:col-span-2"><Card><CardHeader title={`Articles (${filteredItems.length})`} subtitle="Cliquez sur un article pour voir le détail" />
            {filteredItems.length === 0 ? <EmptyState icon={Package} title="Aucun article trouvé" subtitle="Modifiez vos critères de recherche" /> : <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className={thead}><Th>Code</Th><Th>Désignation</Th><Th>Catégorie</Th><ThR>Stock</ThR><ThR>Min</ThR><ThR>Prix</ThR><Th>État</Th></tr></thead><tbody>{filteredItems.map((it) => { const rup = it.availableStock === 0, und = it.availableStock > 0 && it.availableStock <= it.minStock; return <tr key={it.id} onClick={() => setSelItemId(it.id)} className={`border-b border-navy-50 hover:bg-navy-50/50 cursor-pointer transition-colors ${selItemId === it.id ? 'bg-medical-50' : ''}`}><Td className="text-navy-600 font-mono text-xs">{it.code}</Td><Td className="font-medium text-navy-900">{it.name}</Td><Td className="text-navy-600">{CAT[it.category] ?? it.category}</Td><TdR className="font-medium text-navy-900">{it.availableStock}</TdR><TdR className="text-navy-500">{it.minStock}</TdR><TdR className="text-navy-600">{formatFCFA(it.lastPrice)}</TdR><Td>{rup ? <Badge color="red"><AlertCircle className="w-3 h-3" />Rupture</Badge> : und ? <Badge color="amber"><TrendingDown className="w-3 h-3" />Sous min.</Badge> : <Badge color="green"><CheckCircle2 className="w-3 h-3" />Dispo.</Badge>}</Td></tr>; })}</tbody></table></div>}</Card></div>
          <div><Card><CardHeader title="Détail de l'article" subtitle={selItem ? selItem.code : 'Sélectionnez un article'} />
            {selItem ? <div className="p-5 space-y-4">
              <div><p className="text-base font-semibold text-navy-900">{selItem.name}</p><p className="text-sm text-navy-500 mt-0.5">{CAT[selItem.category]}</p></div>
              <div className="grid grid-cols-2 gap-3 text-sm">{[['Emplacement', selItem.location], ['Fournisseur', supName(selItem.supplierId)], ['Unité gestion', selItem.unitManagement], ['Unité dispensation', selItem.unitDispensing], ['Stock disponible', selItem.availableStock], ['Stock réservé', selItem.reservedStock], ['Stock minimum', selItem.minStock], ['Stock maximum', selItem.maxStock], ['Conso. moy./mois', selItem.avgConsumption], ['Dernier prix', formatFCFA(selItem.lastPrice)]].map(([l, v]) => <div key={l as string}><p className="text-navy-400 text-xs">{l}</p><p className="text-navy-800 font-medium">{v}</p></div>)}{selItem.thermoSensitive && <div className="col-span-2"><Badge color="amber"><Thermometer className="w-3 h-3" />Thermosensible</Badge><p className="text-xs text-navy-500 mt-1">{selItem.storageConditions}</p></div>}</div>
              <div><SectionTitle>Lots ({selItemLots.length})</SectionTitle>{selItemLots.length === 0 ? <p className="text-sm text-navy-400">Aucun lot en stock.</p> : <div className="space-y-2">{selItemLots.map((lot) => { const d = daysUntil(lot.expiryDate), exp = isExpired(lot.expiryDate), soon = d >= 0 && d <= 30; return <div key={lot.id} className={`rounded-lg border p-3 text-sm ${lot.blocked ? 'bg-red-50 border-red-200' : exp ? 'bg-red-50 border-red-200' : soon ? 'bg-amber-50 border-amber-200' : 'bg-navy-50 border-navy-100'}`}><div className="flex items-center justify-between mb-1"><span className="font-medium text-navy-800">{lot.lotNumber}</span>{lot.blocked && <Badge color="red"><Lock className="w-3 h-3" />Bloqué</Badge>}</div><div className="text-xs text-navy-500 space-y-0.5"><p>Dispo: {lot.availableQty} · Réservé: {lot.reservedQty} · Quar.: {lot.quarantineQty}</p><p>Péremption: {formatDateShort(lot.expiryDate)} ({exp ? 'Périmé' : `${d}j`})</p></div></div>; })}</div>}</div>
            </div> : <EmptyState icon={Package} title="Aucun article sélectionné" subtitle="Cliquez sur un article du tableau" />}</Card></div>
        </div>
      </div>}

      {/* NEEDS */}
      {tab === 'needs' && <div className="space-y-4">
        <div className="flex items-center justify-between"><p className="text-sm text-navy-500">Expressions de besoin pharmacie — workflow de validation</p><span title="Créer une nouvelle expression de besoin"><Button variant="primary" size="sm" onClick={() => setShowNeedModal(true)}><Plus className="w-4 h-4 mr-1.5" />Nouvelle expression</Button></span></div>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          <div className="lg:col-span-2"><Card><CardHeader title={`Expressions de besoin (${needExpressions.length})`} />{needExpressions.length === 0 ? <EmptyState icon={ShoppingCart} title="Aucune expression de besoin" /> : <div className="divide-y divide-navy-50">{needExpressions.map((ne) => <div key={ne.id} onClick={() => setSelNeedId(ne.id)} className={`p-4 cursor-pointer hover:bg-navy-50/50 transition-colors ${selNeedId === ne.id ? 'bg-medical-50' : ''}`}><div className="flex items-start justify-between mb-2"><div><p className="font-semibold text-navy-900 text-sm">{ne.number}</p><p className="text-xs text-navy-500 mt-0.5">{ne.service} · {ne.period} · {formatDateShort(ne.date)}</p></div><Badge color={needColor(ne.status)}>{ne.urgency === 'urgent' && <AlertTriangle className="w-3 h-3" />}{ne.urgency === 'critique' && <ShieldAlert className="w-3 h-3" />}{NEED_LABEL[ne.status]}</Badge></div><p className="text-xs text-navy-600 line-clamp-2">{ne.justification}</p><div className="flex items-center gap-3 mt-2 text-xs text-navy-400"><span>{ne.items.length} article(s)</span><span>·</span><span>Demandeur: {ne.requester}</span>{ne.validator && <><span>·</span><span>Validateur: {ne.validator}</span></>}</div></div>)}</div>}</Card></div>
          <div><Card><CardHeader title="Détail" subtitle={selNeed ? selNeed.number : 'Sélectionnez une expression'} />{selNeed ? <div className="p-5 space-y-4">
            <div className="flex items-center justify-between"><Badge color={needColor(selNeed.status)}>{NEED_LABEL[selNeed.status]}</Badge><Badge color={selNeed.urgency === 'critique' ? 'red' : selNeed.urgency === 'urgent' ? 'amber' : 'navy'}>{selNeed.urgency === 'critique' ? <ShieldAlert className="w-3 h-3" /> : selNeed.urgency === 'urgent' ? <AlertTriangle className="w-3 h-3" /> : <Info className="w-3 h-3" />}{selNeed.urgency === 'critique' ? 'Critique' : selNeed.urgency === 'urgent' ? 'Urgent' : 'Normal'}</Badge></div>
            <div className="text-sm space-y-1"><p><span className="text-navy-400">Service:</span> <span className="font-medium text-navy-800">{selNeed.service}</span></p><p><span className="text-navy-400">Période:</span> <span className="font-medium text-navy-800">{selNeed.period}</span></p><p><span className="text-navy-400">Date:</span> <span className="font-medium text-navy-800">{formatDate(selNeed.date)}</span></p><p><span className="text-navy-400">Demandeur:</span> <span className="font-medium text-navy-800">{selNeed.requester}</span></p></div>
            <div><p className="text-xs text-navy-400 mb-1">Justification</p><p className="text-sm text-navy-700 bg-navy-50 rounded-lg p-3">{selNeed.justification}</p></div>
            {selNeed.rejectionReason && <div><p className="text-xs text-red-400 mb-1">Motif du rejet</p><p className="text-sm text-red-700 bg-red-50 rounded-lg p-3">{selNeed.rejectionReason}</p></div>}
            <div><SectionTitle>Articles demandés ({selNeed.items.length})</SectionTitle><div className="space-y-2">{selNeed.items.map((it, i) => <div key={i} className="rounded-lg border border-navy-100 p-3 text-sm"><p className="font-medium text-navy-800">{it.itemName}</p><div className="text-xs text-navy-500 mt-1 grid grid-cols-2 gap-1"><span>Disponible: {it.availableQty}</span><span>Min: {it.minStock}</span><span>Conso. moy: {it.avgConsumption}</span><span>Commandé: {it.orderedQty}</span><span className="font-medium text-navy-700">Demandé: {it.requestedQty} {it.unit}</span>{it.validatedQty !== undefined && <span className="font-medium text-green-700">Validé: {it.validatedQty} {it.unit}</span>}</div>{it.comment && <p className="text-xs text-navy-400 mt-1 italic">{it.comment}</p>}</div>)}</div></div>
            <div><SectionTitle>Historique</SectionTitle><div className="space-y-1.5">{selNeed.history.map((h, i) => <div key={i} className="text-xs flex items-start gap-2"><Clock className="w-3 h-3 text-navy-400 mt-0.5 flex-shrink-0" /><div><p className="font-medium text-navy-700">{h.action}</p><p className="text-navy-400">{new Date(h.timestamp).toLocaleString('fr-FR', { dateStyle: 'short', timeStyle: 'short' })}</p>{h.detail && <p className="text-navy-500 mt-0.5">{h.detail}</p>}</div></div>)}</div></div>
            {(selNeed.status === 'soumise' || selNeed.status === 'en-validation') && <div className="space-y-3 border-t border-navy-100 pt-3"><TextArea label="Motif de validation partielle (optionnel)" value={needValReason} onChange={setNeedValReason} rows={2} placeholder="Expliquez l'ajustement..." /><div className="flex flex-wrap gap-2"><Button variant="primary" size="sm" onClick={() => validateNeed(selNeed.id, false)}><CheckCircle2 className="w-4 h-4 mr-1" />Valider</Button><Button variant="secondary" size="sm" onClick={() => validateNeed(selNeed.id, true)}><CheckCircle2 className="w-4 h-4 mr-1" />Validation partielle</Button></div><TextArea label="Motif du rejet" value={needRejReason} onChange={setNeedRejReason} rows={2} placeholder="Indiquez la raison du rejet..." required /><Button variant="danger" size="sm" onClick={() => rejectNeed(selNeed.id)}><X className="w-4 h-4 mr-1" />Rejeter</Button></div>}
          </div> : <EmptyState icon={ShoppingCart} title="Aucune expression sélectionnée" />}</Card></div>
        </div>
        {showNeedModal && <Modal title="Nouvelle expression de besoin" onClose={() => setShowNeedModal(false)} wide><div className="p-5 space-y-4">
          <div className="grid grid-cols-2 gap-3"><Select label="Service demandeur" value={needForm.service} onChange={(v) => setNeedForm((p) => ({ ...p, service: v }))} options={SERVICES.map((s) => ({ value: s, label: s }))} required /><div><label className="block text-sm font-medium text-navy-700 mb-1">Période <span className="text-red-500">*</span></label><input type="text" value={needForm.period} onChange={(e) => setNeedForm((p) => ({ ...p, period: e.target.value }))} placeholder="ex: Octobre 2026" className={inp} /></div></div>
          <Select label="Niveau d'urgence" value={needForm.urgency} onChange={(v) => setNeedForm((p) => ({ ...p, urgency: v as 'normal' | 'urgent' | 'critique' }))} options={[{ value: 'normal', label: 'Normal' }, { value: 'urgent', label: 'Urgent' }, { value: 'critique', label: 'Critique' }]} />
          <TextArea label="Justification" value={needForm.justification} onChange={(v) => setNeedForm((p) => ({ ...p, justification: v }))} placeholder="Décrivez le besoin..." required />
          <div><div className="flex items-center justify-between mb-2"><SectionTitle>Articles demandés</SectionTitle><Button variant="ghost" size="sm" onClick={() => setNeedFormItems((p) => [...p, { itemId: '', requestedQty: 0, comment: '' }])}><Plus className="w-4 h-4 mr-1" />Ajouter</Button></div>{needFormItems.length === 0 ? <p className="text-sm text-navy-400 text-center py-4 bg-navy-50 rounded-lg">Aucun article ajouté.</p> : <div className="space-y-2">{needFormItems.map((ni, idx) => { const it = ni.itemId ? getItem(ni.itemId) : null; return <div key={idx} className="flex items-start gap-2 rounded-lg border border-navy-100 p-3"><div className="flex-1 space-y-2"><Select label="Article" value={ni.itemId} onChange={(v) => setNeedFormItems((p) => p.map((x, i) => i === idx ? { ...x, itemId: v } : x))} options={[{ value: '', label: '— Sélectionner —' }, ...items.map((i) => ({ value: i.id, label: i.name }))]} required />{it && <div className="text-xs text-navy-500 grid grid-cols-2 gap-x-3 gap-y-0.5"><span>Disponible: {it.availableStock}</span><span>Min: {it.minStock}</span><span>Conso. moy: {it.avgConsumption}</span><span>Commandé: {it.orderedQty}</span>{it.availableStock <= it.minStock && <span className="col-span-2 text-amber-600 font-medium">⚠ Suggestion: {Math.max(it.minStock * 2 - it.availableStock, 0)} {it.unitDispensing}</span>}</div>}<div className="grid grid-cols-2 gap-2"><div><label className="block text-xs font-medium text-navy-700 mb-1">Qté demandée</label><input type="number" value={ni.requestedQty || ''} onChange={(e) => setNeedFormItems((p) => p.map((x, i) => i === idx ? { ...x, requestedQty: parseInt(e.target.value) || 0 } : x))} className={inpSm} /></div><div><label className="block text-xs font-medium text-navy-700 mb-1">Commentaire</label><input type="text" value={ni.comment} onChange={(e) => setNeedFormItems((p) => p.map((x, i) => i === idx ? { ...x, comment: e.target.value } : x))} className={inpSm} /></div></div></div><button onClick={() => setNeedFormItems((p) => p.filter((_, i) => i !== idx))} className="text-red-400 hover:text-red-600 mt-6 focus:outline-none focus-visible:ring-2 focus-visible:ring-red-400 rounded"><Trash2 className="w-4 h-4" /></button></div>; })}</div>}</div>
        </div><ModalFooter onCancel={() => setShowNeedModal(false)} onSubmit={submitNeed} submitLabel="Soumettre" /></Modal>}
      </div>}

      {/* QUOTATIONS */}
      {tab === 'quotations' && <div className="space-y-4">
        {Object.entries(quotesByNeed).map(([needId, qs]) => { const need = needExpressions.find((n) => n.id === needId); return <Card key={needId}><CardHeader title={need ? `Cotations — ${need.number}` : 'Cotations'} subtitle={need ? `${need.service} · ${need.period}` : ''} /><div className="p-5"><div className="grid grid-cols-1 md:grid-cols-3 gap-4">{qs.map((q) => { const exp = isExpired(q.expiryDate); return <div key={q.id} className={`rounded-lg border-2 p-4 transition-all ${q.status === 'validee' ? 'border-green-300 bg-green-50' : exp ? 'border-red-200 bg-red-50' : 'border-navy-100'}`}><div className="flex items-center justify-between mb-3"><div><p className="font-semibold text-navy-900 text-sm">{q.supplierName}</p><p className="text-xs text-navy-500">{q.number}</p></div><Badge color={q.status === 'validee' ? 'green' : exp ? 'red' : 'blue'}>{q.status === 'validee' ? <CheckCircle2 className="w-3 h-3" /> : exp ? <Ban className="w-3 h-3" /> : <FileText className="w-3 h-3" />}{QUOTE_LABEL[q.status]}</Badge></div><div className="text-xs text-navy-500 space-y-1 mb-3"><p>Date: {formatDateShort(q.date)}</p><p>Validité: {q.validityDays} jours</p><p className={exp ? 'text-red-600 font-medium' : ''}>Expiration: {formatDateShort(q.expiryDate)} {exp && '(expiré)'}</p></div><div className="space-y-2 mb-3">{q.items.map((it, i) => <div key={i} className="text-xs border-t border-navy-50 pt-2"><p className="font-medium text-navy-800">{it.itemName}</p><div className="text-navy-500 grid grid-cols-2 gap-x-2 mt-1"><span>Prix: {formatFCFA(it.unitPrice)}</span><span>Qté: {it.proposedQty}</span><span>Remise: {it.discount}%</span><span>Délai: {it.deliveryDelay}j</span>{it.dosage && <span>Dosage: {it.dosage}</span>}{it.form && <span>Forme: {it.form}</span>}{it.packaging && <span className="col-span-2">Conditionnement: {it.packaging}</span>}{it.manufacturer && <span className="col-span-2">Fabricant: {it.manufacturer}</span>}{it.registerConformity !== undefined && <span className="col-span-2">Registre: {it.registerConformity ? '✓ Conforme' : '✗ Non conforme'}</span>}{it.remainingValidity !== undefined && <span>Validité restante: {it.remainingValidity} mois</span>}</div><p className="font-bold text-navy-900 mt-1">Total: {formatFCFA(it.totalCost)}</p></div>)}</div><div className="text-xs font-bold text-navy-900 border-t border-navy-100 pt-2">Total devis: {formatFCFA(q.items.reduce((s, it) => s + it.totalCost, 0))}</div>{q.selectionReason && <p className="text-xs text-green-700 mt-2 italic">Motif: {q.selectionReason}</p>}{(q.status === 'en-comparaison' || q.status === 'retenue') && !exp && <div className="mt-3 border-t border-navy-100 pt-3"><Button variant="turquoise" size="sm" className="w-full" onClick={() => setSelQuoteId(q.id)}><CheckCircle2 className="w-4 h-4 mr-1" />Sélectionner ce devis</Button></div>}{exp && (q.status === 'en-comparaison' || q.status === 'retenue') && <div className="mt-3 text-xs text-red-600 bg-red-50 rounded-lg p-2 flex items-center gap-1"><Ban className="w-3.5 h-3.5" />Validation impossible — devis expiré</div>}</div>; })}</div></div></Card>; })}
        {selQuote && <Modal title="Valider le devis" onClose={() => setSelQuoteId(null)}><div className="p-5 space-y-4"><div className="text-sm"><p className="font-medium text-navy-900">{selQuote.supplierName}</p><p className="text-navy-500">{selQuote.number}</p><p className="text-navy-700 mt-2">Total: <span className="font-bold">{formatFCFA(selQuote.items.reduce((s, it) => s + it.totalCost, 0))}</span></p></div><TextArea label="Motif de la sélection" value={selReason} onChange={setSelReason} placeholder="Expliquez pourquoi ce devis est retenu..." required /><div className="flex justify-end gap-2"><Button variant="secondary" size="sm" onClick={() => setSelQuoteId(null)}>Annuler</Button><Button variant="primary" size="sm" onClick={() => validateQuote(selQuote.id)}><CheckCircle2 className="w-4 h-4 mr-1" />Valider</Button></div></div></Modal>}
      </div>}

      {/* RECEPTIONS */}
      {tab === 'receptions' && <div className="space-y-4"><div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <div className="lg:col-span-2"><Card><CardHeader title={`Réceptions (${receptions.length})`} subtitle="Contrôle qualité et conformité" />{receptions.length === 0 ? <EmptyState icon={Truck} title="Aucune réception" /> : <div className="divide-y divide-navy-50">{receptions.map((rec) => <div key={rec.id} onClick={() => setSelRecId(rec.id)} className={`p-4 cursor-pointer hover:bg-navy-50/50 transition-colors ${selRecId === rec.id ? 'bg-medical-50' : ''}`}><div className="flex items-start justify-between mb-2"><div><p className="font-semibold text-navy-900 text-sm">{rec.number}</p><p className="text-xs text-navy-500 mt-0.5">{rec.supplierName} · {formatDateShort(rec.date)} {rec.time} · BL: {rec.deliveryNoteNumber}</p></div><Badge color={rec.decision === 'conforme' ? 'green' : rec.decision === 'partiellement-conforme' ? 'amber' : rec.decision === 'non-conforme' ? 'red' : 'navy'}>{rec.decision === 'conforme' ? <CheckCircle2 className="w-3 h-3" /> : rec.decision === 'non-conforme' ? <X className="w-3 h-3" /> : <AlertTriangle className="w-3 h-3" />}{REC_LABEL[rec.decision]}</Badge></div><div className="text-xs text-navy-500 space-y-0.5">{rec.items.map((ri, i) => <p key={i}>{ri.itemName}: {ri.receivedQty}/{ri.orderedQty} reçus · {ri.acceptedQty} acceptés{ri.refusedQty > 0 && <span className="text-red-600"> · {ri.refusedQty} refusés</span>}</p>)}</div></div>)}</div>}</Card></div>
        <div><Card><CardHeader title="Contrôle qualité" subtitle={selRec ? selRec.number : 'Sélectionnez une réception'} />{selRec ? <div className="p-5 space-y-4">
          <div className="text-sm space-y-1"><p><span className="text-navy-400">Fournisseur:</span> <span className="font-medium text-navy-800">{selRec.supplierName}</span></p><p><span className="text-navy-400">Réceptionné par:</span> <span className="font-medium text-navy-800">{selRec.receiver}</span></p><p><span className="text-navy-400">Bon de livraison:</span> <span className="font-medium text-navy-800">{selRec.deliveryNoteNumber}</span></p></div>
          {selRec.items.map((ri, idx) => <div key={idx} className="rounded-lg border border-navy-100 p-3"><p className="font-medium text-navy-900 text-sm mb-2">{ri.itemName}</p><div className="text-xs text-navy-500 mb-2"><p>Commandé: {ri.orderedQty} · Reçu: {ri.receivedQty} · Lot: {ri.lotNumber}</p><p>Péremption: {formatDateShort(ri.expiryDate)} · Stockage: {ri.storageCondition}</p></div><div className="space-y-1">{[{ f: 'packagingOk', l: 'Conditionnement' }, { f: 'designationOk', l: 'Désignation' }, { f: 'dosageOk', l: 'Dosage' }, { f: 'packagingConformityOk', l: 'Conformité emballage' }, { f: 'quantityOk', l: 'Quantité' }].map((c) => { const k = `${ri.itemId}-${c.f}`, v = recChecks[k] ?? ri[c.f as keyof typeof ri] as boolean; return <label key={c.f} className="flex items-center gap-2 text-xs cursor-pointer"><input type="checkbox" checked={v} onChange={(e) => setRecChecks((p) => ({ ...p, [k]: e.target.checked }))} className="rounded focus:ring-2 focus:ring-medical-400" /><span className={v ? 'text-green-700' : 'text-red-700'}>{v ? '✓' : '✗'} {c.l}</span></label>; })}</div>{ri.comment && <p className="text-xs text-navy-500 mt-2 italic bg-navy-50 rounded p-2">{ri.comment}</p>}</div>)}
          {(selRec.decision === 'partiellement-conforme' || selRec.decision === 'conforme') && <div className="text-xs text-green-700 bg-green-50 rounded-lg p-3 flex items-center gap-2"><PackageCheck className="w-4 h-4" />Stock mis à jour après acceptation.</div>}
          <div className="border-t border-navy-100 pt-3"><SectionTitle>Décision</SectionTitle><div className="flex flex-wrap gap-2"><Button variant="primary" size="sm" onClick={() => applyDecision(selRec.id, 'conforme')}><CheckCircle2 className="w-4 h-4 mr-1" />Conforme</Button><Button variant="secondary" size="sm" onClick={() => applyDecision(selRec.id, 'partiellement-conforme')}><AlertTriangle className="w-4 h-4 mr-1" />Partiel</Button><Button variant="danger" size="sm" onClick={() => applyDecision(selRec.id, 'non-conforme')}><X className="w-4 h-4 mr-1" />Non conforme</Button><Button variant="ghost" size="sm" onClick={() => applyDecision(selRec.id, 'quarantaine')}><Lock className="w-4 h-4 mr-1" />Quarantaine</Button></div></div>
        </div> : <EmptyState icon={ClipboardCheck} title="Aucune réception sélectionnée" />}</Card></div>
      </div></div>}

      {/* ENTRIES */}
      {tab === 'entries' && <div className="max-w-2xl"><Card><CardHeader title="Enregistrer une entrée en stock" subtitle="Génère automatiquement un mouvement de stock" /><div className="p-5 space-y-4">
        <Select label="Type d'entrée" value={entryForm.type} onChange={(v) => setEntryForm((p) => ({ ...p, type: v as MovementType }))} options={ENTRY_TYPES} required />
        <Select label="Article" value={entryForm.itemId} onChange={(v) => { const it = getItem(v); setEntryForm((p) => ({ ...p, itemId: v, lotId: '', origin: it ? supName(it.supplierId) : '' })); }} options={[{ value: '', label: '— Sélectionner —' }, ...items.map((i) => ({ value: i.id, label: `${i.name} (stock: ${i.availableStock})` }))]} required />
        {entryForm.itemId && <Select label="Lot (optionnel)" value={entryForm.lotId} onChange={(v) => setEntryForm((p) => ({ ...p, lotId: v }))} options={[{ value: '', label: '— Aucun / Nouveau lot —' }, ...lots.filter((l) => l.itemId === entryForm.itemId).map((l) => ({ value: l.id, label: `${l.lotNumber} (dispo: ${l.availableQty}, exp: ${formatDateShort(l.expiryDate)})` }))]} />}
        <div><label className="block text-sm font-medium text-navy-700 mb-1">Quantité <span className="text-red-500">*</span></label><input type="number" value={entryForm.quantity || ''} onChange={(e) => setEntryForm((p) => ({ ...p, quantity: parseInt(e.target.value) || 0 }))} className={inp} min={1} /></div>
        <div><label className="block text-sm font-medium text-navy-700 mb-1">Origine</label><input type="text" value={entryForm.origin} onChange={(e) => setEntryForm((p) => ({ ...p, origin: e.target.value }))} placeholder="Fournisseur, service, etc." className={inp} /></div>
        <div className="flex justify-end"><Button variant="primary" onClick={submitEntry}><ArrowDownToLine className="w-4 h-4 mr-1.5" />Enregistrer l'entrée</Button></div>
      </div></Card></div>}

      {/* DISPENSING */}
      {tab === 'dispensing' && <div className="space-y-4">
        <div className="flex items-center justify-between"><p className="text-sm text-navy-500">Dispensations nominatives aux patients</p><span title="Créer une nouvelle dispensation"><Button variant="primary" size="sm" onClick={() => setShowDispForm(true)}><Plus className="w-4 h-4 mr-1.5" />Nouvelle dispensation</Button></span></div>
        <Card><CardHeader title={`Dispensations (${dispensing.length})`} />{dispensing.length === 0 ? <EmptyState icon={ArrowUpFromLine} title="Aucune dispensation" /> : <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className={thead}><Th>Date</Th><Th>Patient</Th><Th>Article</Th><Th>Lot</Th><ThR>Prescrit</ThR><ThR>Délivré</ThR><Th>Service</Th><Th>Pharmacien</Th><Th>Statut</Th></tr></thead><tbody>{dispensing.map((d) => <tr key={d.id} className={trCls}><Td className="text-navy-600 whitespace-nowrap">{formatDateShort(d.date)}</Td><Td className="font-medium text-navy-900">{d.patientName}</Td><Td className="text-navy-700">{d.itemName}</Td><Td className="text-navy-500 font-mono text-xs">{d.lotNumber}</Td><TdR className="text-navy-600">{d.prescribedQty}</TdR><TdR className="font-medium text-navy-900">{d.deliveredQty}</TdR><Td className="text-navy-600">{d.service}</Td><Td className="text-navy-600">{d.pharmacist || '—'}</Td><Td><Badge color={d.status === 'delivree' ? 'green' : d.status === 'a-preparer' ? 'amber' : d.status === 'retournee' ? 'red' : 'navy'}>{d.status === 'delivree' ? <CheckCircle2 className="w-3 h-3" /> : d.status === 'a-preparer' ? <Clock className="w-3 h-3" /> : <AlertCircle className="w-3 h-3" />}{DISP_ST[d.status]}</Badge></Td></tr>)}</tbody></table></div>}</Card>
        {showDispForm && <Modal title="Nouvelle dispensation nominative" onClose={() => setShowDispForm(false)}><div className="p-5 space-y-4">
          <div><label className="block text-sm font-medium text-navy-700 mb-1">Nom du patient <span className="text-red-500">*</span></label><input type="text" value={dispForm.patientName} onChange={(e) => setDispForm((p) => ({ ...p, patientName: e.target.value }))} className={inp} placeholder="ex: Awa Traoré" /></div>
          <div className="grid grid-cols-2 gap-3"><div><label className="block text-sm font-medium text-navy-700 mb-1">N° prescription</label><input type="text" value={dispForm.prescriptionId} onChange={(e) => setDispForm((p) => ({ ...p, prescriptionId: e.target.value }))} className={inp} /></div><Select label="Service" value={dispForm.service} onChange={(v) => setDispForm((p) => ({ ...p, service: v }))} options={SERVICES.map((s) => ({ value: s, label: s }))} /></div>
          <div><label className="block text-sm font-medium text-navy-700 mb-1">Prescripteur</label><input type="text" value={dispForm.prescriber} onChange={(e) => setDispForm((p) => ({ ...p, prescriber: e.target.value }))} className={inp} placeholder="ex: Dr. Yao N'Guessan" /></div>
          <Select label="Article" value={dispForm.itemId} onChange={(v) => setDispForm((p) => ({ ...p, itemId: v, lotId: '' }))} options={[{ value: '', label: '— Sélectionner —' }, ...items.filter((i) => i.availableStock > 0).map((i) => ({ value: i.id, label: `${i.name} (dispo: ${i.availableStock})` }))]} required />
          {dispForm.itemId && <><div><label className="block text-sm font-medium text-navy-700 mb-1">Lot <span className="text-red-500">*</span><span className="text-xs text-navy-400 font-normal ml-2">(FEFO — lot expirant le plus tôt en premier)</span></label><select value={dispForm.lotId} onChange={(e) => setDispForm((p) => ({ ...p, lotId: e.target.value }))} className={inp + ' bg-white'}><option value="">— Sélectionner —</option>{dispLots.map((l) => { const d = daysUntil(l.expiryDate); return <option key={l.id} value={l.id}>{l.lotNumber} — dispo: {l.availableQty} — exp: {formatDateShort(l.expiryDate)} ({d}j)</option>; })}</select></div>{dispBlocked && <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-red-50 border-2 border-red-200 text-red-800 text-sm"><Ban className="w-4 h-4 flex-shrink-0" /><span><strong>{dispBlocked.r}:</strong> {dispBlocked.d} — dispensation impossible.</span></div>}<div className="grid grid-cols-2 gap-3"><div><label className="block text-sm font-medium text-navy-700 mb-1">Qté prescrite</label><input type="number" value={dispForm.prescribedQty || ''} onChange={(e) => setDispForm((p) => ({ ...p, prescribedQty: parseInt(e.target.value) || 0 }))} className={inp} min={0} /></div><div><label className="block text-sm font-medium text-navy-700 mb-1">Qté à délivrer <span className="text-red-500">*</span></label><input type="number" value={dispForm.deliveredQty || ''} onChange={(e) => setDispForm((p) => ({ ...p, deliveredQty: parseInt(e.target.value) || 0 }))} className={inp} min={1} /></div></div></>}
        </div><ModalFooter onCancel={() => setShowDispForm(false)} onSubmit={submitDisp} submitLabel="Délivrer" /></Modal>}
      </div>}

      {/* DOTATIONS */}
      {tab === 'dotations' && <div className="space-y-4">
        <div className="flex items-center justify-between"><p className="text-sm text-navy-500">Dotations aux services de soins</p><span title="Créer une nouvelle dotation"><Button variant="primary" size="sm" onClick={() => setShowDotForm(true)}><Plus className="w-4 h-4 mr-1.5" />Nouvelle dotation</Button></span></div>
        <Card><CardHeader title={`Dotations (${dotations.length})`} />{dotations.length === 0 ? <EmptyState icon={Boxes} title="Aucune dotation" /> : <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className={thead}><Th>Date</Th><Th>Service</Th><Th>Article</Th><Th>Lot</Th><ThR>Demandée</ThR><ThR>Validée</ThR><ThR>Délivrée</ThR><Th>Demandeur</Th><Th>Statut</Th></tr></thead><tbody>{dotations.map((d) => <tr key={d.id} className={trCls}><Td className="text-navy-600 whitespace-nowrap">{formatDateShort(d.date)}</Td><Td className="font-medium text-navy-900">{d.service}</Td><Td className="text-navy-700">{d.itemName}</Td><Td className="text-navy-500 font-mono text-xs">{d.lotNumber}</Td><TdR className="text-navy-600">{d.requestedQty}</TdR><TdR className="text-navy-600">{d.validatedQty}</TdR><TdR className="font-medium text-navy-900">{d.deliveredQty}</TdR><Td className="text-navy-600">{d.requester}</Td><Td><Badge color={d.status === 'delivree' ? 'green' : d.status === 'rejetee' ? 'red' : d.status === 'demandee' ? 'amber' : 'blue'}>{d.status === 'delivree' ? <CheckCircle2 className="w-3 h-3" /> : d.status === 'rejetee' ? <X className="w-3 h-3" /> : <Clock className="w-3 h-3" />}{DOT_ST[d.status]}</Badge></Td></tr>)}</tbody></table></div>}</Card>
        {showDotForm && <Modal title="Nouvelle dotation de service" onClose={() => setShowDotForm(false)}><div className="p-5 space-y-4">
          <Select label="Service destinataire" value={dotForm.service} onChange={(v) => setDotForm((p) => ({ ...p, service: v }))} options={[{ value: '', label: '— Sélectionner —' }, ...SERVICES.map((s) => ({ value: s, label: s }))]} required />
          <div><label className="block text-sm font-medium text-navy-700 mb-1">Demandeur</label><input type="text" value={dotForm.requester} onChange={(e) => setDotForm((p) => ({ ...p, requester: e.target.value }))} className={inp} placeholder="ex: Inf. Brou Éric" /></div>
          <Select label="Article" value={dotForm.itemId} onChange={(v) => setDotForm((p) => ({ ...p, itemId: v, lotId: '' }))} options={[{ value: '', label: '— Sélectionner —' }, ...items.filter((i) => i.availableStock > 0).map((i) => ({ value: i.id, label: `${i.name} (dispo: ${i.availableStock})` }))]} required />
          {dotForm.itemId && <div><label className="block text-sm font-medium text-navy-700 mb-1">Lot <span className="text-red-500">*</span><span className="text-xs text-navy-400 font-normal ml-2">(FEFO)</span></label><select value={dotForm.lotId} onChange={(e) => setDotForm((p) => ({ ...p, lotId: e.target.value }))} className={inp + ' bg-white'}><option value="">— Sélectionner —</option>{dotLots.map((l) => <option key={l.id} value={l.id}>{l.lotNumber} — dispo: {l.availableQty} — exp: {formatDateShort(l.expiryDate)}</option>)}</select></div>}
          <div><label className="block text-sm font-medium text-navy-700 mb-1">Quantité demandée <span className="text-red-500">*</span></label><input type="number" value={dotForm.requestedQty || ''} onChange={(e) => setDotForm((p) => ({ ...p, requestedQty: parseInt(e.target.value) || 0 }))} className={inp} min={1} /></div>
        </div><ModalFooter onCancel={() => setShowDotForm(false)} onSubmit={submitDot} submitLabel="Livrer la dotation" /></Modal>}
      </div>}

      {/* RETURNS */}
      {tab === 'returns' && <div className="space-y-4">
        <div className="flex items-center justify-between"><p className="text-sm text-navy-500">Retours de produits — contrôle et décision</p><span title="Enregistrer un nouveau retour"><Button variant="primary" size="sm" onClick={() => setShowRetForm(true)}><Plus className="w-4 h-4 mr-1.5" />Nouveau retour</Button></span></div>
        <Card><CardHeader title={`Retours (${returns.length})`} />{returns.length === 0 ? <EmptyState icon={RotateCcw} title="Aucun retour enregistré" /> : <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className={thead}><Th>Date</Th><Th>Origine</Th><Th>Article</Th><Th>Lot</Th><ThR>Qté</ThR><Th>Motif</Th><Th>Contrôle</Th><Th>Décision</Th></tr></thead><tbody>{returns.map((r) => <tr key={r.id} className={trCls}><Td className="text-navy-600 whitespace-nowrap">{formatDateShort(r.date)}</Td><Td className="text-navy-700">{r.origin}</Td><Td className="font-medium text-navy-900">{r.itemName}</Td><Td className="text-navy-500 font-mono text-xs">{r.lotNumber}</Td><TdR className="text-navy-900 font-medium">{r.quantity}</TdR><Td className="text-navy-600 max-w-xs">{r.reason}</Td><Td><div className="flex flex-col gap-0.5"><span className={`text-xs ${r.packagingIntact ? 'text-green-600' : 'text-red-600'}`}>{r.packagingIntact ? '✓ Emballage' : '✗ Emballage'}</span><span className={`text-xs ${r.storageRespected ? 'text-green-600' : 'text-red-600'}`}>{r.storageRespected ? '✓ Stockage' : '✗ Stockage'}</span></div></Td><Td><Badge color={r.decision === 'remis-stock' ? 'green' : r.decision === 'quarantaine' ? 'amber' : r.decision === 'a-detruire' || r.decision === 'non-reutilisable' ? 'red' : 'navy'}>{r.decision === 'remis-stock' ? <CheckCircle2 className="w-3 h-3" /> : r.decision === 'quarantaine' ? <Lock className="w-3 h-3" /> : <Trash2 className="w-3 h-3" />}{RET_ST[r.decision]}</Badge></Td></tr>)}</tbody></table></div>}</Card>
        {showRetForm && <Modal title="Enregistrer un retour" onClose={() => setShowRetForm(false)}><div className="p-5 space-y-4">
          <div><label className="block text-sm font-medium text-navy-700 mb-1">Origine <span className="text-red-500">*</span></label><input type="text" value={retForm.origin} onChange={(e) => setRetForm((p) => ({ ...p, origin: e.target.value }))} className={inp} placeholder="ex: Hospitalisation, Bloc opératoire..." /></div>
          <Select label="Article" value={retForm.itemId} onChange={(v) => setRetForm((p) => ({ ...p, itemId: v, lotId: '' }))} options={[{ value: '', label: '— Sélectionner —' }, ...items.map((i) => ({ value: i.id, label: i.name }))]} required />
          {retForm.itemId && <Select label="Lot" value={retForm.lotId} onChange={(v) => setRetForm((p) => ({ ...p, lotId: v }))} options={[{ value: '', label: '— Sélectionner —' }, ...retLots.map((l) => ({ value: l.id, label: `${l.lotNumber} (dispo: ${l.availableQty})` }))]} required />}
          <div><label className="block text-sm font-medium text-navy-700 mb-1">Quantité <span className="text-red-500">*</span></label><input type="number" value={retForm.quantity || ''} onChange={(e) => setRetForm((p) => ({ ...p, quantity: parseInt(e.target.value) || 0 }))} className={inp} min={1} /></div>
          <TextArea label="Motif du retour" value={retForm.reason} onChange={(v) => setRetForm((p) => ({ ...p, reason: v }))} placeholder="Produit non utilisé, emballage intact, etc." required />
          <div className="space-y-2"><label className="flex items-center gap-2 text-sm cursor-pointer"><input type="checkbox" checked={retForm.packagingIntact} onChange={(e) => setRetForm((p) => ({ ...p, packagingIntact: e.target.checked }))} className="rounded focus:ring-2 focus:ring-medical-400" /><span className="text-navy-700">Emballage intact</span></label><label className="flex items-center gap-2 text-sm cursor-pointer"><input type="checkbox" checked={retForm.storageRespected} onChange={(e) => setRetForm((p) => ({ ...p, storageRespected: e.target.checked }))} className="rounded focus:ring-2 focus:ring-medical-400" /><span className="text-navy-700">Conditions de stockage respectées</span></label></div>
          <Select label="Décision de contrôle" value={retForm.decision} onChange={(v) => setRetForm((p) => ({ ...p, decision: v as ReturnDecision }))} options={Object.entries(RET_ST).map(([value, label]) => ({ value, label }))} />
        </div><ModalFooter onCancel={() => setShowRetForm(false)} onSubmit={submitRet} submitLabel="Enregistrer" /></Modal>}
      </div>}

      {/* INVENTORIES */}
      {tab === 'inventories' && <div className="space-y-4">
        <div className="flex items-center justify-between"><p className="text-sm text-navy-500">Inventaires et régularisations de stock</p><span title="Créer un nouvel inventaire"><Button variant="primary" size="sm" onClick={() => setShowInvForm(true)}><Plus className="w-4 h-4 mr-1.5" />Nouvel inventaire</Button></span></div>
        <Card><CardHeader title={`Inventaires (${inventories.length})`} />{inventories.length === 0 ? <EmptyState icon={ClipboardList} title="Aucun inventaire" /> : <div className="divide-y divide-navy-50">{inventories.map((inv) => <div key={inv.id} className="p-4"><div className="flex items-start justify-between mb-3"><div><p className="font-semibold text-navy-900 text-sm">{inv.number}</p><p className="text-xs text-navy-500 mt-0.5">{INV_TYPE[inv.type]} · {formatDate(inv.date)} · {inv.entries.length} ligne(s)</p></div><Badge color={inv.status === 'valide' ? 'green' : inv.status === 'cloture' ? 'navy' : 'amber'}>{inv.status === 'valide' ? <CheckCircle2 className="w-3 h-3" /> : <Clock className="w-3 h-3" />}{INV_ST[inv.status]}</Badge></div><div className="overflow-x-auto"><table className="w-full text-xs"><thead><tr className="border-b border-navy-50 text-left text-navy-400"><th className="px-2 py-2 font-medium">Article</th><th className="px-2 py-2 font-medium">Lot</th><th className="px-2 py-2 font-medium text-right">Théorique</th><th className="px-2 py-2 font-medium text-right">Compté</th><th className="px-2 py-2 font-medium text-right">Écart</th><th className="px-2 py-2 font-medium text-right">Valeur</th><th className="px-2 py-2 font-medium">Motif</th></tr></thead><tbody>{inv.entries.map((e) => <tr key={e.id} className="border-b border-navy-50"><td className="px-2 py-2 text-navy-800">{e.itemName}</td><td className="px-2 py-2 text-navy-500 font-mono">{e.lotNumber ?? '—'}</td><td className="px-2 py-2 text-right text-navy-600">{e.theoreticalStock}</td><td className="px-2 py-2 text-right text-navy-900 font-medium">{e.countedQty}</td><td className={`px-2 py-2 text-right font-medium ${e.gap > 0 ? 'text-green-700' : e.gap < 0 ? 'text-red-700' : 'text-navy-500'}`}>{e.gap > 0 ? '+' : ''}{e.gap}</td><td className={`px-2 py-2 text-right ${e.gapValue > 0 ? 'text-green-700' : e.gapValue < 0 ? 'text-red-700' : 'text-navy-500'}`}>{e.gapValue !== 0 ? formatFCFA(e.gapValue) : '—'}</td><td className="px-2 py-2 text-navy-500 max-w-xs">{e.reason ?? '—'}</td></tr>)}</tbody></table></div></div>)}</div>}</Card>
        {showInvForm && <Modal title="Nouvel inventaire" onClose={() => setShowInvForm(false)} wide><div className="p-5 space-y-4">
          <Select label="Type d'inventaire" value={invForm.type} onChange={(v) => setInvForm((p) => ({ ...p, type: v as Inventory['type'] }))} options={Object.entries(INV_TYPE).map(([value, label]) => ({ value, label }))} />
          <div><div className="flex items-center justify-between mb-2"><SectionTitle>Lignes de comptage</SectionTitle><Button variant="ghost" size="sm" onClick={() => setInvForm((p) => ({ ...p, entries: [...p.entries, { itemId: '', countedQty: 0, reason: '' }] }))}><Plus className="w-4 h-4 mr-1" />Ajouter</Button></div>{invForm.entries.length === 0 ? <p className="text-sm text-navy-400 text-center py-4 bg-navy-50 rounded-lg">Aucune ligne ajoutée.</p> : <div className="space-y-2">{invForm.entries.map((e, idx) => { const it = e.itemId ? getItem(e.itemId) : null; return <div key={idx} className="flex items-start gap-2 rounded-lg border border-navy-100 p-3"><div className="flex-1 space-y-2"><Select label="Article" value={e.itemId} onChange={(v) => setInvForm((p) => ({ ...p, entries: p.entries.map((en, i) => i === idx ? { ...en, itemId: v } : en) }))} options={[{ value: '', label: '— Sélectionner —' }, ...items.map((i) => ({ value: i.id, label: i.name }))]} required />{it && <p className="text-xs text-navy-500">Stock théorique: {it.availableStock} {it.unitDispensing}</p>}<div className="grid grid-cols-2 gap-2"><div><label className="block text-xs font-medium text-navy-700 mb-1">Qté comptée</label><input type="number" value={e.countedQty || ''} onChange={(ev) => setInvForm((p) => ({ ...p, entries: p.entries.map((en, i) => i === idx ? { ...en, countedQty: parseInt(ev.target.value) || 0 } : en) }))} className={inpSm} min={0} /></div><div><label className="block text-xs font-medium text-navy-700 mb-1">Motif</label><input type="text" value={e.reason} onChange={(ev) => setInvForm((p) => ({ ...p, entries: p.entries.map((en, i) => i === idx ? { ...en, reason: ev.target.value } : en) }))} className={inpSm} /></div></div></div><button onClick={() => setInvForm((p) => ({ ...p, entries: p.entries.filter((_, i) => i !== idx) }))} className="text-red-400 hover:text-red-600 mt-6 focus:outline-none focus-visible:ring-2 focus-visible:ring-red-400 rounded"><Trash2 className="w-4 h-4" /></button></div>; })}</div>}</div>
        </div><ModalFooter onCancel={() => setShowInvForm(false)} onSubmit={submitInv} submitLabel="Valider l'inventaire" /></Modal>}
      </div>}

      {/* ALERTS */}
      {tab === 'alerts' && <div className="space-y-4">
        <Card className="p-4"><div className="flex flex-wrap gap-3 items-end">
          <div className="w-56"><Select label="Niveau" value={alertLevel} onChange={setAlertLevel} options={[{ value: 'all', label: 'Tous les niveaux' }, ...Object.entries(ALERT_CFG).map(([value, cfg]) => ({ value, label: cfg.label }))]} /></div>
          <div className="w-56"><Select label="Statut" value={alertStatus} onChange={setAlertStatus} options={[{ value: 'all', label: 'Tous les statuts' }, ...Object.entries(ALERT_ST).map(([value, label]) => ({ value, label }))]} /></div>
          <div className="text-sm text-navy-500 ml-auto">{filteredAlerts.length} alerte(s)</div>
        </div></Card>
        {filteredAlerts.length === 0 ? <Card><EmptyState icon={Bell} title="Aucune alerte" subtitle="Aucune alerte ne correspond aux filtres" /></Card> : <div className="space-y-3">{filteredAlerts.map((a) => { const cfg = ALERT_CFG[a.level], Icon = cfg.icon; return <Card key={a.id} className={`p-4 ${a.level === 'critique' ? 'border-l-4 border-l-red-500' : a.level === 'important' ? 'border-l-4 border-l-amber-500' : ''}`}><div className="flex items-start justify-between gap-4"><div className="flex items-start gap-3 flex-1"><div className={`w-9 h-9 rounded-full flex items-center justify-center flex-shrink-0 ${cfg.bg}`}><Icon className={`w-5 h-5 ${cfg.text}`} /></div><div className="flex-1 min-w-0"><div className="flex items-center gap-2 flex-wrap mb-1"><p className="font-semibold text-navy-900 text-sm">{a.itemName}</p>{a.lotNumber && <span className="text-xs text-navy-500 font-mono">Lot: {a.lotNumber}</span>}<Badge color={cfg.color}><Icon className="w-3 h-3" />{cfg.label}</Badge><Badge color={a.status === 'resolue' || a.status === 'cloturee' ? 'green' : a.status === 'nouvelle' ? 'amber' : 'blue'}>{ALERT_ST[a.status]}</Badge></div><p className="text-sm text-navy-700 mb-1">{a.cause}</p><div className="text-xs text-navy-500 space-y-0.5">{a.availableQty !== undefined && a.threshold !== undefined && <p>Disponible: {a.availableQty} · Seuil: {a.threshold}</p>}<p>Action proposée: {a.proposedAction}</p><p>Responsable: {a.responsible} · {formatDateShort(a.date)}</p></div></div></div><div className="flex flex-col gap-1 flex-shrink-0">{a.status === 'nouvelle' && <Button variant="secondary" size="sm" onClick={() => updateAlert(a.id, 'prise-en-charge', 'Prise en charge')}>Prendre en charge</Button>}{(a.status === 'prise-en-charge' || a.status === 'en-cours') && <><Button variant="primary" size="sm" onClick={() => updateAlert(a.id, 'resolue', 'Résolution')}><CheckCircle2 className="w-3.5 h-3.5 mr-1" />Résoudre</Button><Button variant="ghost" size="sm" onClick={() => updateAlert(a.id, 'justifiee', 'Justification')}>Justifier</Button></>}{a.status !== 'cloturee' && a.status !== 'resolue' && <Button variant="ghost" size="sm" onClick={() => updateAlert(a.id, 'cloturee', 'Clôture')}>Clôturer</Button>}</div></div></Card>; })}</div>}
      </div>}

      {/* MOVEMENTS */}
      {tab === 'movements' && <div className="space-y-4">
        <Card className="p-4"><div className="flex flex-wrap gap-3 items-end">
          <span className="text-sm font-medium text-navy-700 flex items-center gap-1 mr-2"><Filter className="w-4 h-4" />Filtres:</span>
          <div className="w-48"><Select label="Type" value={mvF.type} onChange={(v) => setMvF((p) => ({ ...p, type: v }))} options={[{ value: 'all', label: 'Tous les types' }, ...Object.entries(MV_LABEL).map(([value, label]) => ({ value, label }))]} /></div>
          <div className="w-48"><Select label="Article" value={mvF.itemId} onChange={(v) => setMvF((p) => ({ ...p, itemId: v }))} options={[{ value: 'all', label: 'Tous les articles' }, ...items.map((i) => ({ value: i.id, label: i.name }))]} /></div>
          <div className="w-48"><Select label="Catégorie" value={mvF.category} onChange={(v) => setMvF((p) => ({ ...p, category: v }))} options={[{ value: 'all', label: 'Toutes' }, ...Object.entries(CAT).map(([value, label]) => ({ value, label }))]} /></div>
          <div className="w-40"><Select label="Sens" value={mvF.status} onChange={(v) => setMvF((p) => ({ ...p, status: v }))} options={[{ value: 'all', label: 'Tous' }, { value: 'entree', label: 'Entrées' }, { value: 'sortie', label: 'Sorties' }]} /></div>
          <div className="text-sm text-navy-500 ml-auto">{filteredMv.length} mouvement(s)</div>
        </div></Card>
        <Card><CardHeader title="Historique des mouvements" subtitle="Tous les mouvements de stock pharmacie" />{filteredMv.length === 0 ? <EmptyState icon={History} title="Aucun mouvement" subtitle="Aucun mouvement ne correspond aux filtres" /> : <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className={thead}><Th>Date</Th><Th>Heure</Th><Th>Type</Th><Th>Article</Th><Th>Lot</Th><ThR>Qté</ThR><Th>Origine</Th><Th>Destination</Th><Th>Auteur</Th><ThR>Avant</ThR><ThR>Après</ThR><Th>Motif</Th></tr></thead><tbody>{filteredMv.map((m) => { const isE = ENTRY_MV.includes(m.type); return <tr key={m.id} className={trCls}><Td className="text-navy-600 whitespace-nowrap">{formatDateShort(m.date)}</Td><Td className="text-navy-500">{m.time}</Td><Td><Badge color={isE ? 'green' : 'red'}>{isE ? <ArrowDownToLine className="w-3 h-3" /> : <ArrowUpFromLine className="w-3 h-3" />}{MV_LABEL[m.type]}</Badge></Td><Td className="font-medium text-navy-900">{m.itemName}</Td><Td className="text-navy-500 font-mono text-xs">{m.lotNumber ?? '—'}</Td><TdR className={`font-medium ${isE ? 'text-green-700' : 'text-red-700'}`}>{isE ? '+' : '−'}{m.quantity}</TdR><Td className="text-navy-600">{m.origin ?? '—'}</Td><Td className="text-navy-600">{m.destination ?? '—'}</Td><Td className="text-navy-600">{m.author}</Td><TdR className="text-navy-500">{m.stockBefore}</TdR><TdR className="text-navy-900 font-medium">{m.stockAfter}</TdR><Td className="text-navy-500 max-w-xs truncate">{m.reason ?? '—'}</Td></tr>; })}</tbody></table></div>}</Card>
      </div>}
    </div>
  );
}
